) {
  const { data, error } = await supabaseClient.from("conversations").upsert([
    {
      id: id,
      created_at: new Date(),
    },
  ]);

  if (error) {
    throw new ApplicationError("Failed to create conversation on DB", error);
  }

  return data;
}

