    const { text } = await generateText({
      model: bedrock('anthropic.claude-3-5-sonnet-20240620-v1:0'),
      prompt:
        'Please explain the order in which the default AWS Credential Chain looks up credentials.',
    });
    console.log(text);
  } catch (e) {
    console.error(e);
  }
}

async function nativeBedrock() {
  const client = new BedrockRuntimeClient();
  const payload = {
    anthropic_version: 'bedrock-2023-05-31',
    max_tokens: 4096,
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'text',
            text: 'Please explain the order in which the default AWS Credential Chain looks up credentials.',
          },
        ],
      },
    ],
  };
  const command = new InvokeModelCommand({
    modelId: 'anthropic.claude-3-5-sonnet-20240620-v1:0',
    body: JSON.stringify(payload),
  });

  try {
    const response = await client.send(command);
    const decodedResponseBody = new TextDecoder().decode(response.body);
    const responseBody = JSON.parse(decodedResponseBody);
    console.log(responseBody.content[0].text);
  } catch (e) {
    console.error(e);
  }
}

