### Description

When using createstreamableUI in conjunction with WebSockets on Vercel, an issue occurs where the HTTP connection unexpectedly terminates while WebSocket connections remain active. This behavior is consistently observed when multiple users are connected simultaneously. Each session exhibits a scenario where the createstreamableUI stream suddenly sends a response and prematurely closes the HTTP connection. However, WebSocket continues to transmit data unaffected. This inconsistency leads to partial or incomplete data handling on the client-side, potentially affecting user experience and data integrity. The issue requires investigation to ensure reliable handling of concurrent connections and data streaming across both HTTP and WebSocket protocols.

### Code example

```


const logger = new Logger("app/helpers/ai/websocketHelper.tsx");

export const handleWebSocket = (
  params: Record<string, any>,
  toolTextStream: IStreamableStringValue,
  streamableStatusMessage: IStreamableStringValue,
  streamableUI: ReturnType<typeof createStreamableUI>,
  streamableProgressState: IStreamableProgressState,
  aiState: any,
  action: IAction,
  numOfUIMessages: number,
  baseModelSettings: IBaseModelSettings,
  ai: string,
  user?: User
) => {
  const {
    name,
    id,
    passMessageQueue,
    auth,
    connectionTypeDetails,
  } = action;

  const connTypeDetails = connectionTypeDetails as IWebsocketConnection;

  const CONNECTION_TIMEOUT = connTypeDetails.connectionTimeout
    ? connTypeDetails.connectionTimeout * 1000
    : 5000; // Timeout duration in milliseconds for connection

  const MESSAGE_TIMEOUT = connTypeDetails.timeout
    ? connTypeDetails.timeout * 1000
    : 5000; // Timeout duration in milliseconds for receiving messages

  let fullResponse = "";
  let hasErrorDuringToolCall = false;
  let messageMetadata: undefined | IMessageMetadata;

  let socket: WebSocket;
  let connectionTimeoutId: ReturnType<typeof setTimeout>;
  let messageTimeoutId: ReturnType<typeof setTimeout>;
  const dbStatusMessages: IStatusMessageResponse[] = [];

  const clearAllTimeouts = () => {
    clearTimeout(connectionTimeoutId);
    clearTimeout(messageTimeoutId);
  };

  const handleError = (message: string) => {
    fullResponse += ` <error>${message}<error>`;
    hasErrorDuringToolCall = true;
    logger.error(message);
    clearAllTimeouts();
    streamableUI.done(<ErrorMessage>{message}</ErrorMessage>);
    streamableProgressState?.update({ isStreaming: true });
    streamableStatusMessage?.done();
    streamableProgressState?.done({ isStreaming: false });
    toolTextStream.done();

    if (socket && socket.readyState !== WebSocket.CLOSED) {
      socket.close();
    }
  };

  try {

    socket = new WebSocket(connTypeDetails.url);

    connectionTimeoutId = setTimeout(() => {
      handleError("The connection to the server has timed out.");
    }, CONNECTION_TIMEOUT);

    const resetMessageTimeout = () => {
      clearTimeout(messageTimeoutId);
      messageTimeoutId = setTimeout(() => {
        handleError("The connection to the server has timed out - no message was received from the server.");
      }, MESSAGE_TIMEOUT);
    };

    socket.onopen = () => {
      clearTimeout(connectionTimeoutId);

      delete params.numOfUIMessages;
      params.basePrompt = baseModelSettings.basePrompt;

      const messageQueue = aiState.get().messages || [];

       const userQuery = generateUserQuery(
       auth,
        params,
         passMessageQueue,
         messageQueue,
         user);
      

      socket.send(JSON.stringify(userQuery));

      resetMessageTimeout();
    };

    socket.onmessage = (event) => {
      resetMessageTimeout();
      try {
        const parsedData = JSON.parse(event.data);

        if (parsedData.messageType === WebsocketMessageResponse.FINISHED) {
         
          return socket.close();
        }

        if (parsedData.messageType === WebsocketMessageResponse.STATUS) {
         
          dbStatusMessages.push(parsedData.messageBody);
          streamableStatusMessage?.update(parsedData.messageBody.statusMessage);
        }

       

        if (parsedData.messageType === WebsocketMessageResponse.OUTPUT) {
     
          streamableProgressState?.update({ isStreaming: true });
          fullResponse += parsedData.messageBody.textResponse;
          toolTextStream.append(parsedData.messageBody.textResponse);

        
          streamableUI.update(
            <BotMessage
              content={toolTextStream.value}
              ai={ai}
              numOfUIMessages={numOfUIMessages}
            />
          );

          streamableProgressState?.update({ isStreaming: true });
        }

    
        }
      } catch (error) {
      
        handleError((error as Error).message);
      }
    };

    socket.onerror = (error: any) => {
      handleError("Either the connection to the AI service has been lost or the URL for the AI service is invalid.");
    };

    socket.onclose = (e) => {
 
      clearAllTimeouts();

      aiState.done({
        ...aiState.get(),
        messages: [
          ...aiState.get().messages,
          {
            id: uuidv4(),
            role: LLMRole.ASSISTANT,
            content: [
              {
                type: ToolRole.TOOL_CALL,
                toolName: name,
                toolCallId: id,
                args: params,
              },
            ],
          },
          {
            id: uuidv4(),
            role: LLMRole.TOOL,
            content: [
              {
                type: ToolRole.TOOL_RESULT,
                toolName: name,
                toolCallId: id,
                result: fullResponse,
                isError: hasErrorDuringToolCall,
              },
            ],
            metadata: messageMetadata,
            statusMessages: dbStatusMessages,
          },
        ],
        isNewChat: false,
      });

      if (hasErrorDuringToolCall) return;

      streamableStatusMessage?.done();
      toolTextStream.done();
      streamableUI.done();

      setTimeout(() => {
        streamableProgressState?.done({ isStreaming: false });
      }, 500);
    };
  } catch (error) {
    handleError(
      `An error occurred in creating the connection to the AI service: ${(error as Error).message} in chatId:${aiState.get().chatId
      }`
    );
  }
};
```

