```
import { createAzure } from '@ai-sdk/azure';
import {
  createDataStreamResponse,
  LanguageModelV1,
  smoothStream,
  streamText,
  UIMessage
} from 'ai';
import { NextResponse } from 'next/server';

const modelCache = new Map<string, any>();

export async function POST(req: Request) {
  const startModel = performance.now();
  try {
    const {
      messages,
      conversationId,
      autobotParameter,
      credentials,
    }: {
      messages: UIMessage[];
      conversationId: string;
      autobotParameter: AutobotParameterContextType['autobotParameter'];
      credentials: AutobotParameterContextType['credentials'];
    } = await req.json();

    // Create a cache key using the credentials and model name
    const cacheKey = `${credentials.openai_api_base}_${
      autobotParameter.modelConfiguration.model
    }`;

    let model: LanguageModelV1 = modelCache.get(cacheKey);

    // If model is not in cache, create and cache it
    if (!model) {
      const azure = createAzure({
        resourceName: extractInstanceName(credentials.openai_api_base),
        apiKey: credentials.openai_api_key,
      });
      model = azure(autobotParameter.modelConfiguration.model);
      modelCache.set(cacheKey, model);
    }

    // Do rewriting and context retrieval in parallel
    const contextResponse = await fetchContext(
      messages.map((item) => ({ role: item.role, text: item.content })),
      conversationId,
    );

    const systemPrompt = buildSystemPrompt(
      autobotParameter.prePrompt,
      contextResponse.context,
    );

    const startStream = performance.now();

    return createDataStreamResponse({
      execute: async (dataStream) => {
        // dataStream.writeData('initialized call');

        const result = streamText({
          model,
          system: systemPrompt,
          messages,
          maxSteps: 20,
          experimental_transform: smoothStream({ chunking: 'word' }),
          experimental_generateMessageId: generateUUID,
          tools: toolsSchema,
          experimental_activeTools: [
            'contact_preview_tools',
            'clinic_preview_tools',
            'product_commission_preview_tools',
            'resource_centre_preview_tools',
          ],
          toolCallStreaming: true,
          toolChoice: 'required',
          experimental_telemetry: {
            isEnabled: process.env.NODE_ENV === 'production',
            functionId: 'stream-text',
          },
          temperature:
            autobotParameter.modelConfiguration.parameters.temperature,
          presencePenalty:
            autobotParameter.modelConfiguration.parameters.presence_penalty,
          frequencyPenalty:
            autobotParameter.modelConfiguration.parameters.frequency_penalty,
          maxTokens: autobotParameter.modelConfiguration.parameters.max_tokens,
        });

        // These will still pipe the rest of the stream properly
        result.consumeStream();
        result.mergeIntoDataStream(dataStream);
      },

      onError: (error) => {
        console.error('Stream error:', error);
        return error instanceof Error ? error.message : String(error);
      },
    });
  } catch (error) {
    console.error('🚀 ~ POST ~ error:', error);
    return NextResponse.json({ error: error.message });
  }
}
```

