### Description

The `useChat` hook, when initialized with `DefaultChatTransport`, appears to capture the initial `api route` value at the moment of initialization. Subsequent changes to the state variable passed to the api prop do not reconfigure the transport. This results in all subsequent requests being sent to the original endpoint, even after the state has updated.

This makes it difficult to use the hook in scenarios where the target API endpoint needs to be determined dynamically based on user actions or application state (e.g., routing to different models or actions like /api/suggest-connections vs. /api/summarize-branch).

### Reproduction:
```
'use client';

import { useChat } from '@ai-sdk/react';
import { useState } from 'react';

export default function DynamicApiChatComponent() {
  const [apiRoute, setApiRoute] = useState('/api/chat-a');

  const { messages, sendMessage, error } = useChat({
    // The `api` property is configured with a state variable
    api: apiRoute,
  });

  const handleSendMessage = () => {
    console.log(`Sending message with API route set to: ${apiRoute}`);
    // The hook should use the current value of `apiRoute` here
    sendMessage({ text: 'This is a test.' });
  };

  return (
    <div>
      <h2>Dynamic API Route Test</h2>
      <p>Current API Target: <strong>{apiRoute}</strong></p>

      <div style={{ display: 'flex', gap: '1rem', margin: '1rem 0' }}>
        <button onClick={() => setApiRoute('/api/chat-a')}>
          Set API to Route A
        </button>
        <button onClick={() => setApiRoute('/api/chat-b')}>
          Set API to Route B
        </button>
        <button onClick={handleSendMessage}>
          Send Message
        </button>
      </div>

      {error && <div style={{ color: 'red' }}>Error: {error.message}</div>}

      <div>
        <h3>Messages:</h3>
        {messages.map((m, i) => (
          <div key={i}>{JSON.stringify(m)}</div>
