function removeLastStepStartToContinue(message: UIMessage): void {
	if (message && message.parts) {
		// Find the index of the last step-start part
		const lastStepStartIndex = message.parts.reduce(
			(lastIndex, part, index) => {
				return part.type === "step-start" ? index : lastIndex;
			},
			-1,
		);

		// Remove the last step-start if it exists and is not the first part
		if (lastStepStartIndex > 0) {
			message.parts.splice(lastStepStartIndex, 1);
		}
	}
}
