	apiKey: process.env.OPENAI_API_KEY,
});

const messages: ModelMessage[] = [
	{
		role: "system",
		content: `You are a helpful assistant that can answer questions and help with tasks.`,
	},
	{
		role: "user",
		content: "What is the current price of Bitcoin?",
	},
];

async function main() {
	const abortController = new AbortController();

	setTimeout(() => {
		abortController.abort();
	}, 100); // really short abort time

	const { textStream } = streamText({
		model: openaiProvider.responses("gpt-5-nano"),
		messages,
		abortSignal: abortController.signal,


		onFinish: ({ response }) => {
			console.log(JSON.stringify(response.messages, null, 2));
		},
		onError: (error) => {
			console.error("onError");
		},
		onAbort: ({ steps }) => {
			console.warn("onAbort");
		},
	});

	for await (const delta of textStream) {
		console.log(delta);
	}
}

main();
```

The output is `onError`, not `onAbort` as expected.

