  try {
    const body = await request.json();
    const { messages } = body;

    // Set process.env for AI SDK compatibility
    if (import.meta.env.OPENAI_API_KEY && !process.env.OPENAI_API_KEY) {
      process.env.OPENAI_API_KEY = import.meta.env.OPENAI_API_KEY;
    }

