 private async saveStep(step: StepResult<any>) {
    for (const part of step.content) {
      if (part.type !== 'tool-result' && part.type !== 'tool-error') {
        continue
      }

      let toolPart: ToolUIPart

      if (part.type === 'tool-result') {
        toolPart = {
          toolCallId: part.toolCallId,
          type: `tool-${part.toolName}`,
          state: 'output-available',
          input: part.input,
          output: part.output,
        }
      } else {
        toolPart = {
          toolCallId: part.toolCallId,
          type: `tool-${part.toolName}`,
          state: 'output-error',
          input: part.input,
          errorText:
            part.error instanceof Error
              ? part.error.message
              : String(part.error),
        }
      }

      await saveUIMessage({
        id: uuidv4(),
        role: 'assistant',
        parts: [toolPart]
      })
    }
  }
