        value: {
          type: 'source',
          sourceType: 'url',
          id: 'source-1',
          url: 'https://weather.com',
          title: 'Weather Data Source',
        },
      });

      // First progress
      writer.write({
        type: 'data-progress',
        data: { state: 'Initiating', status: 'loading' },
      });

      // Custom promise in between
      await new Promise(resolve => {
        setTimeout(() => {
          console.log('Custom async task finished');
          resolve(true);
        }, 2000); // wait 2 seconds (example)
      });

      // Second progress after promise resolves
      writer.write({
        type: 'data-progress',
        data: { state: 'Started', status: 'loading' },
      });

      const result = streamText({
        model: openai('gpt-4.1'),
        messages: convertToModelMessages(messages),
        onFinish() {
          writer.write({
            type: 'data-progress',
            data: { state: 'Finished', status: 'loading' },
          });

          // 5. Send completion notification (transient)
          writer.write({
            type: 'data-notification',
            data: { message: 'Request completed', level: 'info' },
            transient: true,
          });
        },
      });

      writer.merge(result.toUIMessageStream());
    },
  });

  return createUIMessageStreamResponse({ stream });
}
