    "ai.usage.outputTokens": 1415,
    "ai.usage.totalTokens": 3639,
    "ai.usage.reasoningTokens": 1088,
    "ai.usage.cachedInputTokens": 0,
    "gen_ai.usage.input_tokens": 2224,
