### Description

It's cool to use `readUIMessageStream` to read chunks, but performance issues will occur while parsing super large messages.

 It will help if I can persist parser's inner state. Here is my implementation for resuming a stream from any position from chunks stream (mostly for connection lost scenario):

```ts
import {
  createStreamingUIMessageState,
  processUIMessageStream,
  type StreamingUIMessageState,
  type UIMessage,
  type UIMessageChunk,
} from "ai";

export type UIMessageStreamCursor<UI_MESSAGE extends UIMessage> = {
  offset: number;
  state: StreamingUIMessageState<UI_MESSAGE>;
  chunk: UIMessageChunk;
};

export function resumeReadingUIMessageStream<UI_MESSAGE extends UIMessage>({
  stream,
  messageId,
  state: propState,
  offset = 0,
}: {
  stream: ReadableStream<UIMessageChunk>;
  messageId: string;
  state?: StreamingUIMessageState<UI_MESSAGE>;
  offset?: number;
}) {
  const state =
    propState ??
    createStreamingUIMessageState<UI_MESSAGE>({
      lastMessage: undefined,
      messageId,
    });

  return new ReadableStream<UIMessageStreamCursor<UI_MESSAGE>>({
    async start(controller) {
      try {
        const res = processUIMessageStream<UI_MESSAGE>({
          stream,
          runUpdateMessageJob(
            job: (options: {
              state: StreamingUIMessageState<UI_MESSAGE>;
              write: () => void;
            }) => Promise<void>
          ) {
            return job({
              state,
              write: () => {},
            });
          },
          onError: (error) => {
            // ignore error chunk
            state.message.metadata ??= {};
            (state.message.metadata as any).__stream_error__ = (
              error as Error
            ).message;
          },
        });

        let chunks = 0;

        for await (const _ of res) {
          controller.enqueue({ offset: chunks + offset, state, chunk: _ });
          chunks++;
        }

        controller.close();
      } catch (e) {
        controller.error(e);
      }
    },
  });
}
```

