  const [objectChanged, setObjectChanged] = useState(false);

  const { object, submit } = useObject({
    api,
    schema: z.object({
      recipe: z.object({
        name: z.string(),
      }),
    }),
  });

  useEffect(() => {
    console.log("object changed", object);
    setObjectChanged(true);
