# Motivation

Sometimes llm model returns an error with NoObjectGeneratedError.
When the type of this error is TypeValidationError, this error can be fixed by adding a message to the next retry as follows.

```typescript
function generate(messages: ModelMessage[], retry: number) {
  do {
    const result = await generateObject({
      model: model('claude-sonnet-4-5-20250929'),
      messages,
      schema: HogeSchema,
      system: SYSTEM_PROMPT,
      maxOutputTokens: 64000,
    });
  } catch (error) {
    if (retry <= 3 && NoObjectGeneratedError.isInstance(error)) {
      const feedbackMessage: ModelMessage = {
        type: "user",
        content: `Fix Error: ${error.cause}`
      }
      return generate(
        [feedbackMessage, ...messages]
      )
    }
  }
}
``` 

# Suggestion

How about adding options called "experimental_retryMessages"?
With this option, I can write code only with the options officially provided.

```typescript
function generate(messages: ModelMessage[]) {
    return await generateObject({
      model: model('claude-sonnet-4-5-20250929'),
      messages,
      schema: HogeSchema,
      system: SYSTEM_PROMPT,
      maxOutputTokens: 64000,
      maxRetries: 3,
      experimental_retryMessages: (messages, error) => {
        if (NoObjectGeneratedError.isInstance(error)) {
          const feedbackMessage: ModelMessage = {
            type: "user",
            content: `Fix Error: ${error.cause}`
          }
          // additional feedback
          return [feedbackMessage, ...messages]
        }
        // If you don't have to change message, just return itself.
        return messages
      }
    });
}
```

