### Describe the bug

When using Effect Schema as messageMetadataSchema.

```typescript
useChat({
    messageMetadataSchema: Schema.standardSchemaV1(metadataSchema),
})
```
There will be an error `Class constructor StandardSchemaV1Class cannot be invoked without 'new'`.

### Possible reason

In the code below, `messageMetadataSchema` is checked by `typeof value === 'function'`.

```typescript
export function asValidator<OBJECT>(
  value: FlexibleValidator<OBJECT>,
): Validator<OBJECT> {
  return isValidator(value)
    ? value
    : typeof value === 'function'
      ? value()
      : standardSchemaValidator(value);
}
```
👇

https://github.com/vercel/ai/blob/5919c9bef27f36f2e8bdb49cef3e02fc1c8ac472/packages/provider-utils/src/validator.ts#L93C1-L98C2


But in Effect Schema,  Schema.standardSchemaV1 returns a class, which is a function, so `standardSchemaValidator` is  never called.

```typescript
export const standardSchemaV1 = <A, I>(
  schema: Schema<A, I, never>,
  overrideOptions?: AST.ParseOptions
): StandardSchemaV1<I, A> & SchemaClass<A, I, never> => {
  const decodeUnknown = ParseResult.decodeUnknown(schema, { errors: "all" })
  return class StandardSchemaV1Class extends make<A, I, never>(schema.ast) {
    static "~standard" = {
      version: 1,
      vendor: "effect",
      validate(value) {
        const scheduler = new scheduler_.SyncScheduler()
        const fiber = Effect.runFork(
          Effect.matchEffect(decodeUnknown(value, overrideOptions), {
            onFailure: makeStandardFailureFromParseIssue,
            onSuccess: (value) => Effect.succeed({ value })
          }),
          { scheduler }
        )
        scheduler.flush()
        const exit = fiber.unsafePoll()
        if (exit) {
          return makeStandardResult(exit)
        }
        return new Promise((resolve) => {
          fiber.addObserver((exit) => {
            resolve(makeStandardResult(exit))
          })
        })
      }
    }
  }
}
```

