### Description

### Bug Report

**Description:**
When using `z.union()` types in a tool's input schema with Google's Gemini model, the SDK generates an invalid JSON payload that Google's API rejects with a "Proto field is not repeating, cannot start list" error.

**Steps to Reproduce:**
1. Create a tool with a union type parameter:
```typescript
calculate: tool({
  description: 'Perform a calculation',
  inputSchema: z.object({
    value: z.union([z.string(), z.number()]),
    operation: z.enum(['double', 'triple']),
  }),
  execute: async ({ value, operation }) => { /* ... */ },
})
```
2. Use the tool with `streamText()` and Google's Gemini model
3. Trigger the tool by sending a message like "double 3"

**Expected Behavior:**
The tool should execute successfully with either string or number input.

**Actual Behavior:**
API returns 400 error:
```
Invalid JSON payload received. Unknown name "type" at 'tools.function_declarations[1].parameters.properties[0].value': Proto field is not repeating, cannot start list.
```

**Error Details:**
- Error occurs at: `tools.function_declarations[1].parameters.properties[0].value`
- Status Code: 400
- Model: `gemini-2.5-flash`

**Environment:**
- AI SDK version: 5.0.90
- Node.js version: v22
- Package: `@ai-sdk/google`

**Additional Context:**

---

The full example code for reproducing the error:

```typescript
import { google } from '@ai-sdk/google';
import { stepCountIs, ModelMessage, streamText, tool } from 'ai';
import 'dotenv/config';
import * as readline from 'node:readline/promises';
import { z } from 'zod';

const terminal = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const messages: ModelMessage[] = [];

async function main() {
  while (true) {
    messages.push({ role: 'user', content: await terminal.question('You: ') });

    const result = streamText({
      model: google('gemini-2.5-flash'),
      tools: {
        weather: tool({
          description: 'Get the weather in a location',
          inputSchema: z.object({
            location: z
              .string()
              .describe('The location to get the weather for'),
          }),
          execute: async ({ location }) => ({
            location,
            temperature: 72 + Math.floor(Math.random() * 21) - 10,
          }),
        }),
        // Test tool with multiple types (tests the anyOf conversion fix)
        calculate: tool({
          description:
            'Perform a calculation with a value that can be string or number',
          inputSchema: z.object({
            value: z
              .union([z.string(), z.number()])
              .describe('A value that can be either a string or a number'),
            operation: z
              .enum(['double', 'triple'])
              .describe('The operation to perform'),
          }),
          execute: async ({ value, operation }) => {
            console.log('value', value);
            console.log('operation', operation);
            const numValue =
              typeof value === 'string' ? parseFloat(value) : value;
            const multiplier = operation === 'double' ? 2 : 3;
            return {
              input: value,
              result: numValue * multiplier,
              operation,
            };
          },
        }),
      },
      stopWhen: stepCountIs(5),
      messages,
    });

    process.stdout.write('\nAssistant: ');
    for await (const delta of result.textStream) {
      process.stdout.write(delta);
    }
    process.stdout.write('\n\n');

    messages.push(...(await result.response).messages);
  }
}

main().catch(console.error);
```


