      imageUrl:
        'https://v3.fal.media/files/rabbit/rmgBxhwGYb2d3pl3x9sKf_output.png',
    },
  },
});
```

### Description

 # Type validation error on finish event with `stopWhen: hasToolCall()` in v6.0.0-beta.99

  ## Description

  When using `streamText` with `stopWhen: hasToolCall("sendMessage")`, the client-side `useChat` hook throws a type validation error when the stream completes. The
  error occurs because the finish event emits `{"type":"finish","finishReason":"tool-calls"}` but the client expects message types like `"text-start"`, `"text-delta"`,
  `"text-end"`, etc.

  ## Error Message

```typescript
  AI_TypeValidationError: Type validation failed: Value: {"type":"finish","finishReason":"tool-calls"}.
  Error message: [
    {
      "code": "invalid_union",
      "errors": [
        [
          {
            "code": "invalid_value",
            "values": ["text-start"],
            "path": ["type"],
            "message": "Invalid input"
          },
          {
            "expected": "string",
            "code": "invalid_type",
            "path": ["id"],
            "message": "Invalid input"
          },
          {
            "code": "unrecognized_keys",
            "keys": ["finishReason"],
            "path": [],
            "message": "Invalid input"
          }
        ],
        [
          {
            "code": "invalid_value",
            "values": ["text-delta"],
            "path": ["type"],
            "message": "Invalid input"
          },
          {
            "expected": "string",
            "code": "invalid_type",
            "path": ["id"],
            "message": "Invalid input"
          },
          {
            "expected": "string",
            "code": "invalid_type",
            "path": ["delta"],
            "message": "Invalid input"
          },
          {
            "code": "unrecognized_keys",
            "keys": ["finishReason"],
            "path": [],
            "message": "Invalid input"
          }
        ],
        ...
      ]
    }
  ]
```

  ## Steps to Reproduce

  ### Server-side (API Route):

  ```typescript
  import { streamText, hasToolCall, createUIMessageStream } from "ai";
  import { google } from "@ai-sdk/google";

  export async function POST(request: NextRequest) {
    const stream = createUIMessageStream({
      execute: ({ writer }) => {
        const result = streamText({
          model: google("gemini-2.5-flash"),
          stopWhen: hasToolCall("sendMessage"), // Stop when sendMessage tool is called
          toolChoice: "required",
          tools: {
            setupCreation: { /* ... */ },
            addMaterial: { /* ... */ },
            editMaterial: { /* ... */ },
            sendMessage: { /* ... */ }, // Final tool that stops the stream
          },
        });

        writer.merge(result.toUIMessageStream());
      },
    });

    return createUIMessageStreamResponse({ stream });
  }
```



  ### Client-side (React Component):


```typescript
 import { useChat } from "@ai-sdk/react";

  const chat = useChat({
    id: "chat-id",
    onError: (error) => {
      console.error("Chat error:", error); // Type validation error logged here
    },
  });
```

###  Expected Behavior

The stream should complete gracefully when the AI calls the sendMessage tool, without throwing type validation errors.

###  Actual Behavior

When the stream finishes with a tool call due to stopWhen, a type validation error is thrown on the client. The chat appears to complete successfully, but the error is logged and sent to error monitoring (Sentry).

##  Workaround

Currently handling this by filtering out the validation error in the onError handler:

```typescript
  onError: (error) => {
    const errorMessage = error instanceof Error ? error.message : String(error);

    // Ignore type validation errors from AI SDK beta
    if (errorMessage.includes("AI_TypeValidationError") ||
        errorMessage.includes("Type validation failed")) {
      console.warn("AI SDK type validation error (ignored):", errorMessage);
      return;
    }

    console.error("Chat error:", error);
    captureException(errorMessage);
  }
```

###  Additional Context

  This appears to be similar to issue #7705 which was fixed in v5.0.4, but is occurring again in the v6 beta. The error seems to happen specifically when:
  - Using stopWhen: hasToolCall(toolName)
  - The AI successfully calls the specified tool
  - The stream emits a finish event with finishReason: "tool-calls"
  - Client-side validation rejects the finish event structure

###  Related Issues

  - #7705 - Similar type validation error in v5.0.0-5.0.3 (fixed in v5.0.4)
  - #8520 - AI_TypeValidationError after tool calls (different root cause)
  - #3433 - finishReason "tool-calls" errors (Gemini-specific schema issues)

### AI SDK Version

- **AI SDK Version**: `ai@6.0.0-beta.99`
- **AI SDK React**: `@ai-sdk/react@3.0.0-beta.99`
- **AI SDK Google**: `@ai-sdk/google@3.0.0-beta.43`
- **Model**: `google("gemini-2.5-flash")`
- **Next.js**: `16.0.3`
- **React**: `19.2.0`

