### Description

The current `experimental_RouterAgent` implementation provides basic agent routing but lacks the flow control capabilities needed for complex, deep agent tasks. The current design:

1. Single-level routing only - Routes to one sub-agent per step, no support for agent chaining or hierarchical delegation
2. No state management - Cannot maintain shared state across agent transitions
3. No conditional branching - Cannot implement complex decision trees or loops
4. No parallel execution - Cannot run multiple agents concurrently and merge results

Not sure how to make the flow more consistent.

Current Implementation


```typescript
export class experimental_RouterAgent<
    SUB_AGENTS extends Record<string, SubAgentSettings>,
> implements RouterAgent<SUB_AGENTS> {
    readonly version = "agent-v1";
    readonly id;
    readonly tools;

    readonly #globalInstructions;
    readonly #settings;
    readonly #subAgents;

    constructor({ id, subAgents, globalInstructions, ...settings }) {
        this.id = id;
        this.#globalInstructions = globalInstructions;
        this.#settings = settings;
        this.#subAgents = subAgents;

        this.tools = Object.values(subAgents).reduce(
            (acc, cur) => ({ ...acc, ...cur.tools }),
            {} as RouterAgent<SUB_AGENTS>["tools"],
        );
    }

    #selectAgent = async (messages: Array<ModelMessage>) => {
        const { output: { agentName, reason } } = await generateText({
            model: this.#settings.model,
            system: buildInstructions(this.#subAgents),
            output: Output.object({ schema: buildSchema(this.#subAgents) }),
            maxRetries: this.#settings.maxRetries,
            temperature: 0,
            messages,
        });

        logger.debug(`Agent selected:${agentName}\nReason: ${reason}`);
        return this.#subAgents[agentName]!;
    };

    #prepareStep: PrepareStepFunction<RouterAgent<SUB_AGENTS>["tools"]> = async (args) => {
        const selectedAgent = await this.#selectAgent(args.messages);

        return {
            model: selectedAgent.model,
            system: this.#globalInstructions?.(selectedAgent.instructions),
            messages: args.messages,
            toolChoice: selectedAgent.toolChoice ?? 
                (Object.keys(selectedAgent.tools ?? {}).length > 0 ? "required" : "none"),
            activeTools: selectedAgent.activeTools ?? Object.keys(selectedAgent.tools ?? {}),
        };
    };

    generate = async (options) => generateText({ ...options, ...this.#settings, tools: this.tools, prepareStep: this.#prepareStep });
    stream = async (options) => streamText({ ...options, ...this.#settings, tools: this.tools, prepareStep: this.#prepareStep });
}
```

