        extractReasoningMiddleware({ tagName: 'thinking' }),
    ]
})

async function main() {
    const agent = new ToolLoopAgent({
        model: wrappedThinkingModel(gateway("anthropic/claude-sonnet-4.5")),
        tools: {
            ask_user: tools.ask_user,
            get_weather: tool({
                description: "Get the weather for a location",
                inputSchema: z.object({
                    location: z.string().describe("The location to get the weather for"),
                }),
                execute: async ({ location }) => {
                    return `The weather in ${location} is sunny.`;
                },
            }),
        },
        instructions: "You are weather agent. You are responsible for providing weather information to the user.",
        onFinish: (event) => {
            console.log("onFinish", event.totalUsage);
