        onStepFinish: (event) => {
            console.log("onStepFinish", event.usage);
        },
    });

    const stream = await agent.stream({
        prompt: "What is the weather in Tokyo?",
    });

    for await (const chunk of stream.textStream) {
        console.log(chunk);
    }
}

main();
