### Description

## Bug: `Controller is already closed` crash in run-tools-transformation when stream errors during tool execution

  `streamText()` with tools crashes with an **unhandled** `TypeError [ERR_INVALID_STATE]: Invalid state: Controller is already closed`
  when the LLM model stream errors while tools are still executing asynchronously. This kills the Node.js process.

```javascript
  TypeError [ERR_INVALID_STATE]: Invalid state: Controller is already closed
      at ReadableStreamDefaultController.enqueue (node:internal/webstreams/readablestream:1077:13)
      at /app/node_modules/ai/dist/index.js:5753:45
      at process.processTicksAndRejections (node:internal/process/task_queues:103:5)
```

  Related: #7518, #6974

  ### Root Cause

  In `run-tools-transformation.ts`, tool executions are fire-and-forget promises. Their `.then()` / `.catch()` / `.finally()` callbacks
   call `toolResultsStreamController.enqueue()` without checking if the controller is still open.

  1. streamText() calls LLM → LLM emits tool-call chunks → tools start executing async
  2. LLM model stream errors (network failure, API 5xx mid-stream, connection drop)
  3. generatorStream.pipeTo() rejects → Promise.all rejects → combined stream errors
  4. stitchableStream.processPull() catches error → calls terminate()
  5. terminate() cancels inner stream readers → toolResultsStreamController is closed
  6. Pending tool .then()/.catch() callbacks fire → enqueue() on closed controller → CRASH

  The cancel propagation from `terminate()` to `toolResultsStreamController` is asynchronous (cascades through `pipeTo` →
  WritableStream → back to ReadableStream), creating a race:
  - **Single fast tool**: completes before cancel reaches the controller — no crash
  - **Multiple/slow tools**: complete after the controller is closed — **CRASH**

  ### Reproduction

  Self-contained script — no API keys needed. Uses a mock model that emits 2 tool calls then errors the stream.

  ```js
  const { streamText, tool, stepCountIs } = require('ai')
  const { z } = require('zod')

  function createCrashingModel() {
    return {
      specificationVersion: 'v3',
      provider: 'mock',
      modelId: 'mock',
      get supportedUrls() { return async () => ({}) },
      doGenerate: async () => { throw new Error('not implemented') },
      doStream: async () => ({
        stream: new ReadableStream({
          start(controller) {
            controller.enqueue({
              type: 'response-metadata',
              id: 'resp-1',
              modelId: 'mock',
              timestamp: new Date(),
            })
            controller.enqueue({
              type: 'tool-call',
              toolCallId: 'call_1',
              toolName: 'slow_tool_a',
              input: '{"q":"a"}',
            })
            controller.enqueue({
              type: 'tool-call',
              toolCallId: 'call_2',
              toolName: 'slow_tool_b',
              input: '{"q":"b"}',
            })
            // Error the stream while tools are still executing
            setTimeout(() => {
              controller.error(new Error('simulated LLM stream error'))
            }, 50)
          },
        }),
      }),
    }
  }

  async function main() {
    let crashed = false
    process.on('unhandledRejection', (err) => {
      if (err?.message?.includes('Controller is already closed')) {
        crashed = true
        console.error('CRASH:', err.message)
      }
    })
    process.on('uncaughtException', (err) => {
      if (err?.message?.includes('Controller is already closed')) {
        crashed = true
        console.error('CRASH:', err.message)
      }
    })

    const result = streamText({
      model: createCrashingModel(),
      messages: [{ role: 'user', content: 'test' }],
      tools: {
        slow_tool_a: tool({
          description: 'Slow tool A',
          parameters: z.object({ q: z.string() }),
          execute: () => new Promise(r => setTimeout(() => r({ ok: true }), 2000)),
        }),
        slow_tool_b: tool({
          description: 'Slow tool B',
          parameters: z.object({ q: z.string() }),
          execute: () => new Promise(r => setTimeout(() => r({ ok: true }), 3000)),
        }),
      },
      toolChoice: 'auto',
      stopWhen: stepCountIs(10),
      onError: () => {},
    })

    try {
      for await (const _ of result.fullStream) {}
    } catch {}

    await new Promise(r => setTimeout(r, 4000))
    console.log(crashed ? 'Bug reproduced' : 'Race did not trigger (retry)')
  }

  main()
```

```bash
# execute the repro script
  node repro.js


  # Output: CRASH: Invalid state: Controller is already closed
  #         Bug reproduced
```


###  Suggested Fix

https://github.com/vercel/ai/pull/12875

  Wrap all toolResultsStreamController.enqueue() and .close() calls in run-tools-transformation.ts with guards:

```javascript
  let _controllerClosed = false;
  const toolResultsStream = new ReadableStream({
    start(controller) { toolResultsStreamController = controller; },
    cancel() { _controllerClosed = true; }
  });

  function safeEnqueue(chunk) {
    if (_controllerClosed) return;
    try { toolResultsStreamController.enqueue(chunk); } catch (e) { _controllerClosed = true; }
  }

  function safeClose() {
    if (_controllerClosed) return;
    try { toolResultsStreamController.close(); _controllerClosed = true; } catch (e) { _controllerClosed = true; }
  }
```

  Note: safeEnqueue/safeClose already exist in the codebase for a different stream controller (around stitchableStream). The same
  pattern just needs to be applied to toolResultsStreamController.

  Verified not fixed in v6.0.101 — all 13 .enqueue() calls on toolResultsStreamController are still unguarded.

