export type StrictToolName = keyof typeof strictToolDefinitions;

export const defaultToolNames = Object.keys(
  strictToolDefinitions,
) as StrictToolName[];

export function buildToolset({
  activeToolNames,
}: {
  activeToolNames?: StrictToolName[];
}): ToolSet {
  if (!activeToolNames || activeToolNames.length === 0) {
    return strictToolDefinitions;
  }

  const entries = activeToolNames.map((name) => [
    name,
    strictToolDefinitions[name],
  ]);

  return Object.fromEntries(entries) as ToolSet;
}
```

